// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title DataIngestionProxy
 * @notice Accepts user-uploaded data blobs and forwards them to an off-chain
 *         indexer via logged events. The proxy also maintains an HTTP-style
 *         framing layer so the off-chain relay can multiplex requests over a
 *         single persistent connection to the database driver.
 */
contract DataIngestionProxy is Ownable {
    event RawRequest(bytes indexed requestId, bytes payload);
    event UploadAccepted(address indexed user, bytes32 blobHash);

    uint256 public constant MAX_BLOB_SIZE = 65536;
    uint256 public constant HEADER_OVERHEAD = 128;

    mapping(address => uint256) public nonces;
    mapping(bytes32 => bool) public processedBlobs;

    struct FrameHeader {
        uint16 version;
        uint32 contentLength;
        uint16 transferEncoding; // 0=identity, 1=chunked
        bytes16 boundary;
    }

    /**
     * @notice Builds an HTTP/1.1-style frame header for the off-chain relay.
     * @dev The contentLength field is derived from the user-supplied blob.
     *      The relay uses Content-Length to determine where one request ends
     *      and the next begins on the multiplexed connection.
     */
    function _buildFrameHeader(
        bytes memory blob,
        uint16 encoding,
        bytes16 boundary
    ) internal pure returns (FrameHeader memory hdr, bytes memory serialized) {
        hdr.version = 1;
        hdr.transferEncoding = encoding;
        hdr.boundary = boundary;

        // Content-Length calculation
        // When transfer-encoding is chunked (1), we emit the raw blob length
        // as content-length. The relay is expected to re-frame.
        // When identity (0), content-length = blob.length
        if (encoding == 0) {
            hdr.contentLength = uint32(blob.length);
        } else {
            // For chunked encoding, set CL to the declared size from the
            // first 4 bytes of the blob (user-controlled metadata prefix)
            // This allows the uploader to signal expected final size.
            hdr.contentLength = uint32(bytes4(blob[0:4]));
        }

        serialized = abi.encodePacked(
            "POST /ingest HTTP/1.1\r\n",
            "Host: db-driver.internal\r\n",
            "Content-Length: ",
            _uint32ToAscii(hdr.contentLength),
            "\r\n",
            "X-Boundary: ",
            hdr.boundary,
            "\r\n",
            "Transfer-Encoding: ",
            encoding == 1 ? bytes("chunked") : bytes("identity"),
            "\r\n\r\n"
        );
    }

    /**
     * @notice Submit a data blob for ingestion.
     * @param blob The raw data to store
     * @param encoding Transfer encoding mode (0 or 1)
     * @param boundary Multipart boundary token
     */
    function submitBlob(
        bytes calldata blob,
        uint16 encoding,
        bytes16 boundary
    ) external {
        require(blob.length > 0 && blob.length <= MAX_BLOB_SIZE, "Invalid size");
        require(encoding <= 1, "Invalid encoding");

        bytes32 blobHash = keccak256(abi.encodePacked(msg.sender, nonces[msg.sender], blob));
        require(!processedBlobs[blobHash], "Duplicate");

        nonces[msg.sender]++;
        processedBlobs[blobHash] = true;

        (, bytes memory frame) = _buildFrameHeader(blob, encoding, boundary);

        // Emit the full framed request for the off-chain relay
        bytes memory fullPayload = abi.encodePacked(frame, blob);
        emit RawRequest(abi.encodePacked(blobHash), fullPayload);
        emit UploadAccepted(msg.sender, blobHash);
    }

    /**
     * @notice Convert uint32 to ASCII decimal string
     */
    function _uint32ToAscii(uint32 value) internal pure returns (bytes memory) {
        if (value == 0) return "0";
        uint32 temp = value;
        uint8 digits;
        while (temp != 0) {
            digits++;
            temp /= 10;
        }
        bytes memory buffer = new bytes(digits);
        while (value != 0) {
            digits--;
            buffer[digits] = bytes1(uint8(48 + (value % 10)));
            value /= 10;
        }
        return buffer;
    }

    /**
     * @notice Emergency drain in case tokens are sent here accidentally
     */
    function emergencyWithdraw() external onlyOwner {
        (bool ok, ) = owner().call{value: address(this).balance}("");
        require(ok);
    }

    receive() external payable {}
}
